// ===== EP CONFIG SYSTEM — colores, modo oscuro, acento, lado =====
function getThemeDefaultHex(){
  try{
    // 1) intento por radio checked — cubre 3 temas reales de Eminus (morado #5b2c83, índigo #673fb4, verde #2e7d32)
    // OJO: solo selectores con checked — un img[src*="tema"] sin checked siempre matcheaba el 1º (tema1)
    // y devolvía morado aunque el tema real fuera otro.
    const checked = document.querySelector('.theme_radio_button mat-radio-button.mat-radio-checked img, .theme_radio_button .mat-radio-checked img, mat-radio-button.mat-radio-checked img, .theme_radio_button [aria-checked="true"] img, .theme_radio_button mat-radio-button[aria-checked="true"] img');
    if(checked){
      const src=(checked.getAttribute('src')||'').toLowerCase();
      if(src.includes('ic_tema1') || src.includes('tema1')) return '#5b2c83';
      if(src.includes('theme2') || src.includes('tema2')) return '#673fb4';
      if(src.includes('theme3') || src.includes('tema3') || src.includes('2e7d32') || src.includes('ic_tema3')) return '#2e7d32';
      // fallback por id cercano
      const id=(checked.closest('mat-radio-button')?.id||'').toLowerCase();
      if(id==='mat-radio-6') return '#5b2c83';
      if(id==='mat-radio-7') return '#673fb4';
      if(id==='mat-radio-8') return '#2e7d32';
      // si src contiene color hex directo
      const hexM = src.match(/#([0-9a-f]{6})/i);
      if(hexM) return '#'+hexM[1].toLowerCase();
    }
    // 2) fallback por índice del radio checked (1º= morado, 2º= índigo, 3º= verde) — robusto si img cambió
    try{
      const radios = Array.from(document.querySelectorAll('.theme_radio_button mat-radio-button, mat-radio-button'));
      const idx = radios.findIndex(r=> r.classList.contains('mat-radio-checked') || r.getAttribute('aria-checked')==='true' || r.querySelector('.mat-radio-checked'));
      if(idx===0) return '#5b2c83';
      if(idx===1) return '#673fb4';
      if(idx===2) return '#2e7d32';
    }catch{}
  }catch{}
  return null;
}
function watchEminusTheme(){
  try{
    if(window.__ep_theme_obs) return;
    const group=document.querySelector('.theme_radio_button');
    const headerEl=document.querySelector('.m-brand, .m-header, .m-brand__tools, [class*="m-brand--skin-"]');
    let debounce=null;
    const handleThemeChange=()=>{
      clearTimeout(debounce);
      debounce=setTimeout(()=>{
        const hex=getThemeDefaultHex() || (function(){ try{ const el=document.querySelector('.m-brand__tools.m-stack__item.m-brand--skin-purple, .m-brand--skin-purple, .m-brand__tools.m-brand--skin-purple, .m-brand.m-brand--skin-purple, .m-brand--skin-blue, .m-brand__tools.m-brand--skin-blue, .m-brand.m-brand--skin-blue, .m-brand--skin-green, .m-brand.m-brand--skin-green, .m-brand__tools.m-brand--skin-green, .m-brand__tools, .m-brand, .m-header, [class*="m-brand--skin-"]'); if(!el) return null; const brandStyle=document.querySelector('#ep-brand-override'); const prevCss=brandStyle?brandStyle.textContent:''; const prevBg=el.style.background; const prevBgC=el.style.backgroundColor; const prevBd=el.style.borderColor; if(brandStyle) brandStyle.textContent=''; el.style.background=''; el.style.backgroundColor=''; el.style.borderColor=''; const cs=getComputedStyle(el).backgroundColor; if(brandStyle) brandStyle.textContent=prevCss; el.style.background=prevBg; el.style.backgroundColor=prevBgC; el.style.borderColor=prevBd; const m=String(cs).match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/); if(!m) return null; const toHex=n=> ('0'+parseInt(n,10).toString(16)).slice(-2); const h='#'+toHex(m[1])+toHex(m[2])+toHex(m[3]); if(h==='#000000'||h==='#ffffff'||h==='#f8fafc') return null; return h.toLowerCase(); }catch{return null; } })();
        if(!hex) return;
        const prev=(function(){ try{ return (localStorage.getItem('ep_brand_default') || sessionStorage.getItem('ep_brand_default') || '').toLowerCase(); }catch{ return ''; } })();
        if(prev===hex.toLowerCase()) return;
        try{ localStorage.setItem('ep_brand_default', hex.toLowerCase()); }catch{}
        try{ sessionStorage.setItem('ep_brand_default', hex.toLowerCase()); }catch{}
        try{
          const cfgRaw=localStorage.getItem('ep_cfg');
          const j=cfgRaw?JSON.parse(cfgRaw):{};
          const isDefaultAccent = !j.accent || j.accent.toLowerCase()===EP_DEFAULT_CONFIG.accent.toLowerCase() || j.accent.toLowerCase()==='#004a99' || j.accent.toLowerCase()==='#7c3aed' || j.accent.toLowerCase()===prev;
          if(isDefaultAccent){
            // fuerza recálculo con nuevo brand
            const fresh=loadEpConfig();
            applyEpConfig(fresh);
          }
          // actualiza siempre la fila "Default" para que no mienta (aunque accent sea custom)
          const w=document.querySelector('.ep-config-widget');
          if(w){
            const sec=w.querySelector('[data-cfg-section="appearance"]');
            if(sec) sec.dataset.rendered='';
            renderEpConfigSections(w);
          }
        }catch{}
      }, 120);
    };
    if(group){
      // FIX SISTÉMICO: un solo observer para group (antes creaba 1 por cada img+radio → fuga + trabas)
      window.__ep_theme_obs=new MutationObserver(handleThemeChange);
      window.__ep_theme_obs.observe(group, {attributes:true, subtree:true, attributeFilter:['class','style','src','aria-checked']});
    } else {
      // si group aún no existe (SPA), observa body hasta que aparezca y también header — con throttle
      window.__ep_theme_obs=new MutationObserver(()=>{
        if(window.__ep_theme_pending) return; window.__ep_theme_pending=true;
        requestAnimationFrame(()=>{ window.__ep_theme_pending=false;
        const g=document.querySelector('.theme_radio_button');
        if(g){ try{ window.__ep_theme_obs.disconnect(); }catch{} window.__ep_theme_obs=null; watchEminusTheme(); handleThemeChange(); }
        });
      });
      try{ window.__ep_theme_obs.observe(document.documentElement, {childList:true, subtree:true}); }catch{}
    }
    // observa también header directo por si tema cambia sin tocar radio (ej: carga inicial)
    if(headerEl && !window.__ep_header_theme_obs){
      window.__ep_header_theme_obs=new MutationObserver(handleThemeChange);
      try{ window.__ep_header_theme_obs.observe(headerEl, {attributes:true, attributeFilter:['class','style']}); }catch{}
    }
    // chequeo inicial retardado por si tema ya es #2e7d32 y caché era viejo
    setTimeout(handleThemeChange, 800);
  }catch{}
}
/* FIX SISTÉMICO: lado aplicado ANTES del primer paint para no ver flash derecha→izquierda */
function __ep_applySideInstant(side){
  try{
    const s = side==='left' ? 'left' : 'right';
    const wrappers = document.querySelectorAll('.ep-wrapper');
    const stacks = document.querySelectorAll('.ep-right-stack');
    wrappers.forEach(w=>{
      const prev = w.style.transition;
      w.style.transition='none';
      w.classList.remove('ep-side-left','ep-side-right');
      w.classList.add(s==='left'?'ep-side-left':'ep-side-right');
      let isFixed = w.style.position === 'fixed';
      try { if (!isFixed && getComputedStyle(w).position === 'fixed') isFixed = true; } catch {}
      if (isFixed) {
        // flotante: se mueve con left/right; los widgets siempre en columna
        w.style.left = s==='left' ? '16px' : 'auto';
        w.style.right = s==='left' ? 'auto' : '16px';
        try { w.style.flexDirection = 'column'; } catch {}
      } else {
        // en flujo (lista): el lado = orden dentro de .ep-list-wrap
        try {
          const wrap = w.closest('.ep-list-wrap');
          const content = wrap && wrap.querySelector('.d-flex.flex-column.align-items-center.mt-3');
          if (wrap && content) {
            if (s === 'left') wrap.insertBefore(w, content);
            else wrap.appendChild(w);
          }
          try { w.style.flexDirection = 'column'; } catch {}
        } catch {}
      }
      void w.offsetHeight;
      setTimeout(()=>{ w.style.transition=prev; }, 40);
    });
    stacks.forEach(st=>{
      const prevS = st.style.transition;
      st.style.transition='none';
      st.style.marginLeft=''; st.style.marginRight='';
      void st.offsetHeight;
      setTimeout(()=>{ st.style.transition=prevS; }, 40);
    });
    return true;
  }catch{ return false; }
}
(function(){
  try{
    if(!location.href.includes('/eminus4/page/')) return;
    const raw=localStorage.getItem('ep_cfg');
    const j=raw?JSON.parse(raw):{};
    const side=j.side||'right';
    const styleId='ep-side-early';
    if(!document.getElementById(styleId)){
      const s=document.createElement('style');
      s.id=styleId;
      s.textContent='.wrapper{transition:none !important} .ep-right-stack{transition:none !important}';
      (document.head||document.documentElement).appendChild(s);
      setTimeout(()=>{ try{s.remove();}catch{} }, 80);
    }
    __ep_applySideInstant(side);
    // FIX SISTÉMICO: observer anti-loop — evita trabar eminus por mutaciones recursivas
    // Antes observaba documentElement subtree sin throttle y __ep_applySideInstant mutaba DOM → loop infinito
    if(!window.__ep_side_obs){
      window.__ep_side_mutating = false;
      window.__ep_side_raf = 0;
      window.__ep_side_obs = new MutationObserver(()=>{
        if(window.__ep_side_mutating) return; // FIX: no re-entrar mientras aplicamos lado
        // FIX SISTÉMICO: usa window.* para nunca ReferenceError aunque var no exista (lienzo SPA)
        if(Date.now()-(window.__ep_side_last||0) < 700) return; window.__ep_side_last=Date.now(); try{ __ep_side_last=window.__ep_side_last; }catch{}
        if(window.__ep_side_raf) return; // FIX: batch rAF evita storm 100+ callbacks/seg
        window.__ep_side_raf = requestAnimationFrame(()=>{ window.__ep_side_raf=0;
        try{
          const cfgRaw=localStorage.getItem('ep_cfg');
          const cfgJ=cfgRaw?JSON.parse(cfgRaw):{};
          const curSide=cfgJ.side||'right';
          const w=document.querySelector('.ep-wrapper');
          if(!w) return;
          const hasCorrectClass = w.classList.contains(curSide==='left'?'ep-side-left':'ep-side-right');
          if(!hasCorrectClass){
            window.__ep_side_mutating = true;
            try{ window.__ep_side_obs.disconnect(); }catch{}
            __ep_applySideInstant(curSide);
            try{ window.__ep_side_obs.observe(document.documentElement, {childList:true, subtree:true}); }catch{}
            setTimeout(()=>{ window.__ep_side_mutating=false; }, 50);
          } else {
            // verifica colocación real: orden en lista u offset en flotante
            let needFix = false;
            try{
              const lw = w.closest('.ep-list-wrap');
              if(lw){
                const content = lw.querySelector('.d-flex.flex-column.align-items-center.mt-3');
                if(content){
                  const wlBefore = !!(w.compareDocumentPosition(content) & 4);
                  if((curSide==='left') !== wlBefore) needFix = true;
                }
              } else if(getComputedStyle(w).position==='fixed'){
                if(curSide==='left' && w.style.left!=='16px') needFix = true;
                if(curSide!=='left' && w.style.right!=='16px') needFix = true;
              }
            }catch{}
            if(needFix){
              window.__ep_side_mutating = true;
              try{ window.__ep_side_obs.disconnect(); }catch{}
              __ep_applySideInstant(curSide);
              try{ window.__ep_side_obs.observe(document.documentElement, {childList:true, subtree:true}); }catch{}
              setTimeout(()=>{ window.__ep_side_mutating=false; }, 50);
            }
          }
        }catch{ window.__ep_side_mutating=false; }
        });
      });
      try{ window.__ep_side_obs.observe(document.documentElement, {childList:true, subtree:true}); }catch{}
    }
  }catch{}
})();
