function loadEpConfig(){
  try{
    // FIX persistencia: Eminus hace localStorage.clear() al cerrar sesión;
    // cadena localStorage → sessionStorage (sobrevive al logout en la pestaña) → defaults
    let raw = null;
    try { raw = localStorage.getItem('ep_cfg'); } catch {}
    if (!raw) { try { raw = sessionStorage.getItem('ep_cfg'); } catch {} }
    const j = raw ? JSON.parse(raw) : {};
    // Follow-mode: sin elección explícita del usuario (accentByUser), el accent sigue al
    // detectado de Eminus. El morado #5b2c83 guardado por versiones viejas como "default"
    // se considera rancio y se reemplaza por detección — salvo que el usuario lo haya
    // elegido en Configuración (accentByUser=1), en cuyo caso se respeta siempre.
    // Migración única: customs viejos (no cyan/azul/morado) se marcan como elección explícita.
    try{
      if(j.accent && /^#[0-9a-f]{6}$/i.test(String(j.accent))){
        const _a=String(j.accent).toLowerCase();
        if(!j.accentByUser && _a!=='#06b6d4' && _a!=='#004a99' && _a!=='#5b2c83'){
          j.accentByUser=1;
          try{ saveEpConfig(j); }catch{}
        }
      }
    }catch{}
    const _acc=(j.accent?String(j.accent):'').toLowerCase();
    const _follow=!j.accentByUser && (!_acc || _acc===EP_DEFAULT_CONFIG.accent.toLowerCase() || _acc==='#004a99' || _acc==='#5b2c83');
    if(_follow){
      const det=getBrandDefaultHex();
      if(det && det!=='#004a99' && det!=='#10b981') j.accent=det;
      // sin detección: el morado/azul rancio (defaults de versiones viejas) se suelta
      // al default de la extensión; el morado solo vuelve por detección real o elección explícita
      else if(!j.accent || _acc==='#004a99' || _acc==='#5b2c83') delete j.accent;
    }
    return { ...EP_DEFAULT_CONFIG, ...j, urgency: __ep_normUrgency(j.urgency) };
  }catch{
    try{ const det=getBrandDefaultHex(); return { ...EP_DEFAULT_CONFIG, accent: det||EP_DEFAULT_CONFIG.accent }; }catch{ return { ...EP_DEFAULT_CONFIG }; }
  }
}
function saveEpConfig(cfg){
  try{ localStorage.setItem('ep_cfg', JSON.stringify(cfg)); }catch{}
  try{ sessionStorage.setItem('ep_cfg', JSON.stringify(cfg)); }catch{}
  try{ chrome.storage.local.set({ ep_cfg: cfg }).catch(()=>{}); }catch{}
}
// FIX persistencia: restaura config del respaldo (chrome.storage sobrevive al clear de Eminus
