// Default headers for the new API
const DEFAULT_HEADERS = {
  "authority": "eminus.uv.mx",
  "method": "GET",
  "scheme": "https",
  "accept": "application/json, text/plain, */*",
  "accept-encoding": "gzip, deflate, br, zstd",
  "accept-language": "es-419,es-US;q=0.9,es;q=0.8",
  "priority": "u=1, i",
  "sec-ch-ua": '"Not;A=Brand";v="99", "Google Chrome";v="139", "Chromium";v="139"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "empty",
  "sec-fetch-mode": "cors",
  "sec-fetch-site": "same-origin"
};

/**
 * Makes an API request to Eminus with proper authentication
 */
async function makeApiRequest(bearerToken, endpoint, referer = "https://eminus.uv.mx/eminus4/page/course/list", isRetry = false) {
  const __ep_timeoutMs = isRetry ? 20000 : 12000;
  try {
    console.log(`ðŸŒ Making API request to: ${endpoint}`);
    
    const headers = {
      ...DEFAULT_HEADERS,
      "authorization": `Bearer ${bearerToken}`,
      "referer": referer,
      "path": endpoint
    };

    // FIX SISTÉMICO: timeout 12s + AbortController para no trabar eminus si API cuelga
    const ctrl = new AbortController();
    const t = setTimeout(()=> ctrl.abort(), __ep_timeoutMs);
    let response;
    try{
      response = await fetch(`${BASE_URL}${endpoint}`, {
        method: "GET",
        headers: headers,
        credentials: 'include',
        signal: ctrl.signal
      });
    } finally { clearTimeout(t); }

    console.log(`ðŸ“¡ API Response status: ${response.status} for ${endpoint}`);

    if (!response.ok) {
      if(response.status===401){
        console.warn(`[EP] 401 no autorizado para ${endpoint} — sesión expirada, espera token`);
        // FIX: espera breve por si login/autofill está en curso y token aún no se setea (caso zs23023489 justo después de autofill)
        const freshToken = localStorage.getItem('accessToken');
        if(freshToken && freshToken !== bearerToken){
          console.log('[EP] Token fresco detectado, reintenta con nuevo token');
          headers.authorization = `Bearer ${freshToken}`;
          try{ const ac=new AbortController(); const tt=setTimeout(()=>ac.abort(),8000); try{ const retry = await fetch(`${BASE_URL}${endpoint}`, { method: "GET", headers: headers, credentials: 'include', signal: ac.signal }); if(retry.ok){ const t2 = await retry.text(); if(!t2.trim()) return []; try{ return JSON.parse(t2); }catch{ return []; } } } finally{ clearTimeout(tt); } }catch{}
        }
        // si aún 401, espera 1.5s por si login termina y reintenta una vez más
        await new Promise(r=>setTimeout(r, 1500));
        const retryToken = localStorage.getItem('accessToken');
        if(retryToken && retryToken !== bearerToken){
          headers.authorization = `Bearer ${retryToken}`;
          try{ const ac2=new AbortController(); const tt2=setTimeout(()=>ac2.abort(),8000); try{ const retry2 = await fetch(`${BASE_URL}${endpoint}`, { method: "GET", headers: headers, credentials: 'include', signal: ac2.signal }); if(retry2.ok){ const t3 = await retry2.text(); if(!t3.trim()) return []; try{ return JSON.parse(t3); }catch{ return []; } } } finally{ clearTimeout(tt2); } }catch{}
        }
        // último intento: auto-login Eminus con credenciales capturadas (si existen)
        try{
          const creds = await new Promise(res=>{ try{ chrome.runtime.sendMessage({action:'getCredentials'}, r=> res(r?.creds||null)); }catch{ res(null); } });
          if(creds && creds.username && creds.password){
            console.log('[EP] 401 Eminus, intenta auto-login con', creds.username);
            const ok = await new Promise(res=>{ try{ chrome.runtime.sendMessage({action:'eminusAutoLogin', username: creds.username, password: creds.password}, r=> res(r)); }catch{ res(null); } });
            if(ok && ok.ok){
              await new Promise(r=>setTimeout(r, 1200));
              const newTok = localStorage.getItem('accessToken');
              const useTok = newTok || retryToken || freshToken;
              if(useTok){
                headers.authorization = `Bearer ${useTok}`;
                try{ const ac3=new AbortController(); const tt3=setTimeout(()=>ac3.abort(),8000); try{ const retry3 = await fetch(`${BASE_URL}${endpoint}`, { method: "GET", headers: headers, credentials: 'include', signal: ac3.signal }); if(retry3.ok){ const t4 = await retry3.text(); if(!t4.trim()) return []; try{ return JSON.parse(t4); }catch{ return []; } } } finally{ clearTimeout(tt3); } }catch{}
              }
            }
          }
        }catch{}
        console.warn(`[EP] 401 persiste para ${endpoint} — sesión realmente expirada`);
        return [];
      }
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const text = await response.text();
    if (!text.trim()) {
      // FIX SISTÉMICO: Empty es normal en cursos sin actividades/exámenes (ej: 135758) — no es error
      // Antes spameaba ⚠ï¸ en consola confundiendo con fallo de horario. Ahora log silencioso solo para debug.
      const isEmptyOk = endpoint.includes('getActividadesEstudiante') || endpoint.includes('getExamenesEst') || endpoint.includes('getForos');
      if (isEmptyOk) {
        console.log(`ℹï¸ Sin datos en ${endpoint} (curso sin contenido)`);
      } else {
        console.warn(`⚠ï¸ Empty response from ${endpoint}`);
      }
      return [];
    }

    const data = JSON.parse(text);
    console.log(`✅ Successfully parsed ${Array.isArray(data) ? data.length : 'non-array'} items from ${endpoint}`);
    return data;
  } catch (error) {
    const __ep_isAbort = error && (error.name === 'AbortError' || String((error && error.message) || '').toLowerCase().includes('abort'));
    if (__ep_isAbort && !isRetry) {
      console.warn(`[EP] Timeout en ${endpoint}, reintentando una vez con más tiempo…`);
      return makeApiRequest(bearerToken, endpoint, referer, true);
    }
    if (__ep_isAbort) console.warn(`[EP] Timeout persistente en ${endpoint} (red lenta o API caída)`);
    else console.error(`❌ API request failed for ${endpoint}:`, error);
    return [];
  }
}

/**
 * Gets all courses for the authenticated user
 */
// FIX velocidad: comparte vuelo + memo 60s (facilitadores, badge y tareas pedían lo mismo en paralelo)
async function getAllCourses(bearerToken) {
  try {
    if (window.__ep_coursesPromise) return await window.__ep_coursesPromise;
    if (window.__ep_coursesMemo && window.__ep_coursesMemo.items && (Date.now() - window.__ep_coursesMemo.ts) < 60000) return window.__ep_coursesMemo.items;
  } catch {}
  // FIX velocidad: sessionStorage sobrevive al reload en la misma pestaña (lectura sync, sin red)
  try {
    const tokNow = bearerToken || localStorage.getItem('accessToken');
    if (tokNow) {
      const rawS = sessionStorage.getItem('ep_courses_sess');
      if (rawS) {
        const jS = JSON.parse(rawS);
        if (jS && Array.isArray(jS.active) && jS.active.length && (Date.now() - jS.ts) < 5 * 60 * 1000 && (!jS.user || !__ep_tokenUser(tokNow) || jS.user === __ep_tokenUser(tokNow))) {
          try { window.__ep_active_courses_cache = jS.active; window.__ep_courses_cache = jS.active; } catch {}
          __ep_getAllCoursesReal(tokNow).then(r => {
            try {
              if (r && r.length) {
                window.__ep_coursesMemo = { items: r, ts: Date.now() };
                try { sessionStorage.setItem('ep_courses_sess', JSON.stringify({ active: r, ts: Date.now(), user: __ep_tokenUser(tokNow) })); } catch {}
              }
            } catch {}
          }).catch(() => {});
          return jS.active;
        }
      }
    }
  } catch {}
  window.__ep_coursesPromise = __ep_getAllCoursesReal(bearerToken);
  let res = [];
  try { res = await window.__ep_coursesPromise; } catch {} finally { try { window.__ep_coursesPromise = null; } catch {} }
  try { if (res && res.length) { window.__ep_coursesMemo = { items: res, ts: Date.now() }; try { sessionStorage.setItem('ep_courses_sess', JSON.stringify({ active: res, ts: Date.now(), user: __ep_tokenUser(bearerToken) })); } catch {} } } catch {}
  return res;
}
async function __ep_getAllCoursesReal(bearerToken) {
  try {
    const courses = await makeApiRequest(
      bearerToken, 
      API_ENDPOINTS.COURSES,
      "https://eminus.uv.mx/eminus4/page/course/list"
    );

    if (!courses || courses.length === 0) {
      // FIX: 401 ya retorna [] silencioso, no es error si no hay cursos o sesión expirada
      if(!courses || courses.length===0) console.log('[EP] Sin cursos (vacío o 401) — no es error');
      return [];
    }

    // Filter active courses - be more flexible with dates
    const activeCourses = courses.filter(courseWrapper => {
      const course = courseWrapper.curso;
      const endDate = new Date(course.fechaTermino);
      const now = new Date();
      const isNotArchived = course.archivado === 0;
      // Include courses that ended recently (within 30 days) to catch late submissions
      const isActiveOrRecent = endDate > (now.getTime() - (30 * 24 * 60 * 60 * 1000));
      
      console.log(`Course "${course.nombre}": endDate=${endDate.toLocaleDateString()}, archived=${course.archivado}, show=${isNotArchived && isActiveOrRecent}`);
      
      return isNotArchived && isActiveOrRecent;
    });

    console.log(`Found ${activeCourses.length} active courses out of ${courses.length} total`);
    try{ window.__ep_courses_cache = courses; }catch{}
    try{ window.__ep_active_courses_cache = activeCourses; }catch{}
    return activeCourses;
  } catch (error) {
    if(String(error.message).includes('No courses found') || String(error.message).includes('401')) console.log('[EP] getAllCourses sin datos (sesión o sin cursos)');
    else console.error("Error fetching courses:", error);
    return [];
  }
}

/**
 * Gets all activities for a specific course
 */
async function getActivitiesByCourse(bearerToken, courseId) {
  try {
    const activities = await makeApiRequest(
      bearerToken,
      `${API_ENDPOINTS.ACTIVITIES}/${courseId}`,
      "https://eminus.uv.mx/eminus4/page/course/activity"
    );

    if (!activities || activities.length === 0) {
      return [];
    }
    // FIX: cosecha docente por curso de la respuesta (sin fetch extra)
    try { if (Array.isArray(activities)) activities.forEach(a => { try { __ep_harvestTeacher(a, courseId); } catch {} }); } catch {}

    // Filter pending activities - be more flexible with status
    const now = new Date();
    const pendingActivities = activities.filter(activity => {
      const deadline = new Date(activity.fechaTermino);
      // Show activities that are not fully completed (estadoEntrega could be 0, null, or undefined)
      // and deadline hasn't passed by more than 7 days (to show recently due activities)
      const isNotSubmitted = !activity.estadoEntrega || activity.estadoEntrega === 0 || activity.estadoEntrega === null;
      const isWithinTimeframe = deadline > (now.getTime() - (7 * 24 * 60 * 60 * 1000)); // 7 days grace period
      
      console.log(`Activity "${activity.titulo}": deadline=${deadline.toLocaleDateString()}, submitted=${activity.estadoEntrega}, show=${isNotSubmitted && isWithinTimeframe}`);
      
      return isNotSubmitted && isWithinTimeframe;
    });

    console.log(`Found ${pendingActivities.length} pending activities out of ${activities.length} total for course ${courseId}`);
    return pendingActivities;
  } catch (error) {
    console.error(`Error fetching activities for course ${courseId}:`, error);
    return [];
  }
}

