function decodeHTMLEntitiesEP(str) {
  const t = document.createElement('textarea');
  t.innerHTML = str;
  return t.value;
}
function normalizeAIText(str) {
  let s = String(str || "").replace(/<system-reminder>[\s\S]*?<\/system-reminder>/gi, "").replace(/<system-reminder[\s\S]*$/gi, "").replace(/Your operational mode has changed[\s\S]*?as needed\./gi, "").trim();
  s = decodeHTMLEntitiesEP(s);
  s = s.replace(/\r\n/g, "\n");
  // quita HTML real pero preserva saltos para listas
  s = s.replace(/<[^>]*>/g, "");
  // headers markdown
  s = s.replace(/^###\s+(.*)$/gm, "<h4>$1</h4>");
  s = s.replace(/^##\s+(.*)$/gm, "<h4>$1</h4>");
  s = s.replace(/^#\s+(.*)$/gm, "<h4>$1</h4>");
  // bold y code antes de listas
  s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
  s = s.replace(/__(.*?)__/g, "<strong>$1</strong>");
  s = s.replace(/`([^`]+)`/g, "<code>$1</code>");
  // italic simple (evita **)
  s = s.replace(/(?<!\*)\*(?!\*)(.*?)(?<!\*)\*(?!\*)/g, "<em>$1</em>");
  // procesa lineas para listas y parrafos — formato pro sin importar como venga
  let lines = s.split("\n");
  let html = "";
  let inOl = false, inUl = false;
  const flushLists = () => { if(inOl){ html += "</ol>"; inOl=false; } if(inUl){ html += "</ul>"; inUl=false; } };
  for (let raw of lines) {
    let line = raw.trim();
    if (!line) { flushLists(); continue; }
    // si ya es header
    if (/^<h4>.*<\/h4>$/.test(line)) { flushLists(); html += line.replace("<h4>","<h4 style='font-size:13px;font-weight:700;margin:10px 0 6px;color:#0f172a;'>").replace("</h4>","</h4>"); continue; }
    let mOl = line.match(/^(\d+)[\.\)]\s+(.*)/);
    if (mOl) {
      if (!inOl) { flushLists(); html += "<ol>"; inOl = true; }
      html += "<li>" + mOl[2] + "</li>";
      continue;
    }
    let mUl = line.match(/^[-•*]\s+(.*)/);
    if (mUl) {
      if (!inUl) { flushLists(); html += "<ul>"; inUl = true; }
      html += "<li>" + mUl[1] + "</li>";
      continue;
    }
    // Detecta linea que es solo bold como titulo (ej: <strong>Guía paso a paso:</strong>)
    if (/^<strong>.*<\/strong>:?$/.test(line) && !inOl && !inUl) {
      flushLists();
      html += "<div style='font-weight:700;color:#0f172a;margin:8px 0 6px;font-size:13px;'>" + line.replace(/<\/?strong>/g,"") + "</div>";
      continue;
    }
    flushLists();
    // parrafo normal
    html += "<p>" + line + "</p>";
  }
  flushLists();
  // si no se genero estructura (una sola linea sin listas), usa line breaks simples
  if (!html.includes("<p") && !html.includes("<ol") && !html.includes("<ul") && !html.includes("<h4") && !html.includes("<div")) {
    // fallback simple: respeta saltos originales con <br>
    let simple = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>").replace(/\n/g, "<br>");
    return simple.trim();
  }
  // limpia p vacios y normaliza
  html = html.replace(/<p>\s*<\/p>/g, "");
  // si html solo tiene texto sin tags (caso raro), envuelve
  if (!html.trim()) {
    html = "<p>" + s.replace(/\n/g, "<br>") + "</p>";
  }
  return html.trim();
}
/**
 * Returns description summary — SOLO LLM REMOTO vía background → Worker
 * Sin heurística local: todo resumen viene del modelo remoto.
 */
async function fetchSummaryDescription(activityId, description) {
  if (!description || description.trim() === '') return "Sin descripción";
  const decoded = decodeHTMLEntitiesEP(description);
  const div = document.createElement('div');
  div.innerHTML = decoded;
  const text = div.textContent.trim();
  if (!text) return "Sin descripción";
  const clean = normalizeAIText(text).slice(0, 4000);
  const resp = await chrome.runtime.sendMessage({ action: 'summarizeTask', id: activityId, description: clean });
  if (resp && resp.error) throw new Error(resp.error);
  const summary = resp && (resp.summary || resp.answer) ? String(resp.summary || resp.answer).trim() : "";
  if (!summary) throw new Error("IA vacía");
  if (/The user wants a one-sentence summary|Based on the provided context|system-reminder|Your operational mode|markdown format/i.test(summary)) throw new Error("thinking-leak");
  await chrome.storage.local.set({ [`ep_ai3_${activityId}`]: summary });
  // Purga restos de cachés viejas para este id (ya nunca se leen)
  try { await chrome.storage.local.remove([String(activityId), `ep_desc_${activityId}`, `ep_ai2_${activityId}`]); } catch {}
  return summary;
}

/**
 * Gets cached description — SOLO caché v3 del LLM remoto; todo lo anterior se ignora y se purga
 */
async function getDescription(activityId, description) {
  try {
    // Solo se lee la caché v3 (LLM remoto con techo actual). Todo lo anterior se ignora.
    const cached = await chrome.storage.local.get([`ep_ai3_${activityId}`]);
    const val = cached[`ep_ai3_${activityId}`];
    const s = String(val || "");
    const looksReal = val && s.length >= 15 && val !== "Sin descripción" && !s.trim().startsWith('{') && !s.includes('"summary"');
    if (looksReal) {
      return val;
    }
    // Purga diferida de keys viejas
    try { await chrome.storage.local.remove([String(activityId), `ep_desc_${activityId}`, `ep_ai2_${activityId}`]); } catch {}
    return await fetchSummaryDescription(activityId, description);
  } catch (error) {
    console.error("Error getting description (IA remota):", error);
    return "IA no disponible — reintenta en unos segundos";
  }
}

/**
 * Cleans up cache — FIX SISTÉMICO: solo borra keys de descripciones, no todo storage
 */
async function cleanupCache(currentActivities) {
  // Purga única de cachés viejas (era local + v2 del techo de 200 tokens): una vez por instalación
  try {
    if (!localStorage.getItem('ep_legacypurge_v3')) {
      const all = await chrome.storage.local.get();
      const legacy = Object.keys(all).filter(k => k.startsWith('ep_desc_') || k.startsWith('ep_ai2_') || /^\d+$/.test(k));
      if (legacy.length) await chrome.storage.local.remove(legacy);
      localStorage.setItem('ep_legacypurge_v3', '1');
    }
  } catch {}
  // FIX velocidad: leer TODO el storage en cada apertura es caro (guarda HTML de MiUV);
  // basta limpiar 1 vez por hora
  try {
    const lastClean = parseInt(localStorage.getItem('ep_cacheclean_ts') || '0', 10);
    if (Date.now() - lastClean < 60 * 60 * 1000) return;
    localStorage.setItem('ep_cacheclean_ts', String(Date.now()));
  } catch {}
  try {
    const allCached = await chrome.storage.local.get();
    const cachedKeys = Object.keys(allCached);
    const currentIds = new Set(currentActivities.map(a => String(a.idActividad)));
    const toRemove = cachedKeys.filter(k => {
      // v3 (LLM actual): ep_ai3_<id> | legacy: ep_ai2_* (techo 200), ep_desc_<id> y <id> pelado (se purgan siempre)
      if (k.startsWith('ep_ai2_')) return true; // caché v2 truncada: fuera siempre
      if (k.startsWith('ep_ai3_')) { const base = k.slice(7); return /^\d+$/.test(base) && !currentIds.has(base); }
      const base = k.startsWith('ep_desc_') ? k.slice(8) : k;
      if (!/^\d+$/.test(base)) return false;
      return true; // legacy: fuera, esté o no la actividad
    });
    if (toRemove.length) await chrome.storage.local.remove(toRemove);
  } catch (error) {
    console.error("Error cleaning up cache:", error);
  }
}

/**
 * Fetches activity detail when list doesn't bring descripcion
 */
// FIX: cosecha docente/facilitador de respuestas que YA se traen (actividades/detalles).
// Los endpoints de miembros son especulativos; esto usa datos verificados sin fetch extra.
function __ep_harvestTeacher(obj, courseId) {
  try {
    if (!obj || typeof obj !== 'object' || !courseId) return;
    const keys = ['facilitador', 'nombreFacilitador', 'facilitadorNombre', 'docente', 'nombreDocente', 'docenteNombre', 'profesor', 'nombreProfesor', 'profesorNombre', 'tutor', 'nombreTutor', 'tutorNombre', 'maestro', 'nombreMaestro', 'catedratico', 'instructor', 'nombreInstructor', 'encargado', 'responsable', 'asesor', 'titular', 'nombreTitular', 'ponente', 'profesorAsignado', 'docenteAsignado'];
    let name = '';
    for (const k of keys) {
      const v = obj[k];
      if (typeof v === 'string' && v.trim() && v.trim().toLowerCase() !== 'facilitador') { name = v.trim(); break; }
      if (v && typeof v === 'object') {
        const full = [v.nombre, v.paterno, v.materno].filter(Boolean).join(' ').trim() || v.nombreCompleto || v.nombre || '';
        if (full && full.toLowerCase() !== 'facilitador') { name = full; break; }
      }
    }
    const pkeys = ['fotoFacilitador', 'fotoDocente', 'fotoProfesor', 'fotoTutor', 'foto', 'ruta', 'imagen', 'fotoPerfil'];
    let img = '';
    for (const k of pkeys) { const v = obj[k]; if (typeof v === 'string' && v.trim()) { img = v.trim(); break; } }
    if (!name && !img) return;
    window.__ep_teacher_by_course = window.__ep_teacher_by_course || {};
    const ck = String(courseId);
    const prev = window.__ep_teacher_by_course[ck];
    if (name) {
      if (!prev || !prev.name || prev.name === 'Facilitador') window.__ep_teacher_by_course[ck] = { name, img: (img || (prev && prev.img) || '') };
      else if (img && !prev.img) prev.img = img;
    } else if (img && prev && !prev.img) prev.img = img;
  } catch {}
}
// FIX verificado (401 = ruta real, resto 404): solo /getActividad/{idCurso}/{idActividad} existe.
// Antes probaba 5 endpoints especulativos en serie por actividad (hasta 5×12s de timeout).
async function fetchActivityDetail(bearerToken, courseId, activityId) {
  try {
    const data = await makeApiRequest(bearerToken, `/eminusapi/api/Actividad/getActividad/${courseId}/${activityId}`);
    if (!data) return "";
    // Puede venir como objeto o array
    const obj = Array.isArray(data) ? data[0] : data;
    if (!obj) return "";
    try { __ep_harvestTeacher(obj, courseId); } catch {}
    const d = obj.descripcion || obj.instrucciones || obj.detalle || obj.contenido || obj.observaciones || obj.descripcionHtml || "";
    if (d && String(d).trim()) return String(d);
  } catch {}
  return "";
}

/**
 * Resumen rapido SIN worker: solo lee cache v3 (nunca llama al LLM).
 * Para la ruta critica; el mini-resumen de cada tarjeta se completa en fondo al renderizar.
 */
async function __ep_descFast(activityId){
  try{
    const cached = await chrome.storage.local.get([`ep_ai3_${activityId}`]);
    const val = cached[`ep_ai3_${activityId}`];
    const s = String(val || '');
    if(val && s.length >= 15 && val !== 'Sin descripción' && !s.trim().startsWith('{') && !s.includes('"summary"')) return val;
  }catch{}
  return null;
}
// Extracto plano de respaldo (sin IA) para pintar al instante
function __ep_excerpt(raw){
  try{
    const t = document.createElement('div');
    t.innerHTML = String(raw || '');
    return (t.textContent || '').replace(/\s+/g,' ').trim().slice(0, 220);
  }catch{ try{ return String(raw || '').slice(0, 220); }catch{ return ''; } }
}

/**
 * Processes activities — FIX SISTÉMICO anti-trabas: batch 5 en vez de Promise.all masivo
 * Antes: 30 actividades * 5 endpoints detalle en paralelo → 150 fetch colapsaba red + storage → freeze
 * Ahora: chunks de 5 para no saturar event loop ni quota chrome.storage
 */
async function processActivities(activities) {
  const CHUNK = 5;
  const out = [];
  // ÓPTIMO: urgentes primero (vencidas → vencen ≤7d → resto) para que sus resúmenes IA
  // resuelvan antes. No se descarta nada: mismo array, distinto orden.
  const rankOf = (a) => {
    const t = Date.parse(a.fechaEntrega || a.fechaTermino || '') || Infinity;
    const now = Date.now();
    if (t < now) return 0;
    if (t - now <= 7 * 24 * 3600 * 1000) return 1;
    return 2;
  };
  const ordered = (activities || []).slice().sort((x, y) => (rankOf(x) - rankOf(y)) || ((Date.parse(x.fechaEntrega || x.fechaTermino || '') || Infinity) - (Date.parse(y.fechaEntrega || y.fechaTermino || '') || Infinity)));
  for(let c=0;c<ordered.length;c+=CHUNK){
    const chunk = ordered.slice(c, c+CHUNK);
    const res = await Promise.all(chunk.map(async activity => {
    try {
    let rawDesc = activity.descripcion || activity.instrucciones || activity.detalle || activity.observaciones || activity.contenido || activity.descripcionHtml || "";
    // Si la lista no trae descripción, intenta endpoint de detalle (como hace la página al dar Ver)
    if (!rawDesc || !String(rawDesc).trim()) {
      console.log(`ðŸ” Actividad "${activity.titulo}" sin descripción en lista (keys: ${Object.keys(activity).join(',')}) → probando detalle...`);
      try {
        const tok = localStorage.getItem("accessToken");
        // FIX: probing diferido al backfill (no bloquea pintura); aqui solo se marca faltante
        void tok;
      } catch {}
      if (!rawDesc) console.log(`ℹï¸ Actividad "${activity.titulo}" sin descripción ni en detalle`);
    }
    // FIX velocidad: resumen IA FUERA de la ruta critica — aqui solo cache/storage + extracto.
    // El mini-resumen de cada tarjeta se completa en fondo al renderizar (ya era async).
    let summary = "Sin descripción";
    if(rawDesc){
      try{ summary = (await __ep_descFast(activity.idActividad)) || __ep_excerpt(rawDesc) || "Sin descripción"; }catch{ try{ summary = __ep_excerpt(rawDesc) || "Sin descripción"; }catch{} }
    }
    return {
      idCurso: activity.idCurso,
      idActividad: activity.idActividad,
      fechaEntrega: activity.fechaEntrega,
      descripcionOriginal: rawDesc,
      descripcion: summary,
      titulo: activity.titulo,
      fechaInicio: activity.fechaInicio,
      fechaTermino: activity.fechaTermino,
      estadoEntrega: activity.estadoEntrega,
      valor: activity.valor || 0,
      porEquipos: activity.porEquipos || 0,
      nombreEquipo: activity.nombreEquipo || null,
      courseName: activity.courseName,
      course: activity.course,
      type: activity.type
    };
    } catch (e) {
      // FIX robustez: un fallo en una actividad no tumba su chunk ni la omite — se conserva básica
      console.warn('[EP] actividad con error, se conserva básica:', activity && activity.idActividad);
      return {
        idCurso: activity.idCurso,
        idActividad: activity.idActividad,
        fechaEntrega: activity.fechaEntrega,
        descripcionOriginal: "",
        descripcion: "Sin descripción",
        titulo: activity.titulo || 'Actividad',
        fechaInicio: activity.fechaInicio,
        fechaTermino: activity.fechaTermino,
        estadoEntrega: activity.estadoEntrega,
        valor: activity.valor || 0,
        porEquipos: 0,
        nombreEquipo: null,
        courseName: activity.courseName,
        course: activity.course,
        type: 'activity'
      };
    }
  }));
    out.push(...res);
  }
  return out;
}

/**
 * Gets all pending activities for all active courses
 */
async function getAllPendingActivities(bearerToken) {
  try {
    try{ window.__ep_perf.fetch0 = Math.round(performance.now() - (window.__ep_t0 || performance.now())); }catch{}
    console.log('ðŸ” Starting to fetch all pending activities...');
    
    // Get all active courses
    const courses = await getAllCourses(bearerToken);
    
    if (!courses || courses.length === 0) {
      console.log('❌ No courses found');
      return [];
    }

    console.log(`ðŸ“š Processing ${courses.length} courses...`);
    const allActivities = [];

    // FIX SISTÉMICO: paralelo con concurrency 3 en vez de serial (antes 6 cursos * 1.5s = 9s trabado)
    // Usa Promise.allSettled para no fallar todo si un curso falla, main thread no bloqueado
    const results = await Promise.allSettled(courses.map(async (courseWrapper)=>{
      const courseId = courseWrapper.curso.idCurso;
      const courseName = courseWrapper.curso.nombre;
      console.log(`ðŸ“– Fetching activities for course: ${courseName} (ID: ${courseId})`);
      const activities = await getActivitiesByCourse(bearerToken, courseId);
      return activities.map(activity => ({
        ...activity,
        courseName: courseName,
        course: courseName,
        type: 'activity'
      }));
    }));
    for(const r of results){ if(r.status==='fulfilled' && r.value.length){ allActivities.push(...r.value); console.log(`✅ Added ${r.value.length} activities`); } else if(r.status==='rejected'){ console.warn('[EP] curso activities falló', r.reason); } }

    console.log(`ðŸ“‹ Total activities found: ${allActivities.length}`);

    // Process activities (add descriptions)
    const processedActivities = await processActivities(allActivities);
    
    // Clean up cache
    await cleanupCache(processedActivities);
    
    // Sort by deadline (earliest first)
    try{ window.__ep_perf.fetch1 = Math.round(performance.now() - (window.__ep_t0 || performance.now())); }catch{}
    const sortedActivities = processedActivities.sort((a, b) => {
      return new Date(a.fechaTermino).getTime() - new Date(b.fechaTermino).getTime();
    });

    console.log(`ðŸŽ¯ Final result: ${sortedActivities.length} pending activities to display`);
    return sortedActivities;
  } catch (error) {
    console.error("❌ Error getting all pending activities:", error);
    return [];
  }
}

