/**
 * Sets up the content container with tabs and proper structure
 */
function setupContentContainer(container, loaderContainer, loader) {
  // Check if container is already set up
  if (container.querySelector('.container-header')) {
    return;
  }
  try{ __ep_perfMark('shell', true); }catch{}
  
  // Remove loader
  if (loader && loader.parentNode) {
    loader.remove();
  }
  if (loaderContainer && loaderContainer.parentNode) {
    loaderContainer.remove();
  }
  
  // Clear container
  container.innerHTML = '';
  
  // Create header container — FIX SISTÉMICO COMPACTO PROFESIONAL
  const headerContainer = document.createElement('div');
  headerContainer.className = 'container-header';
  
  // Create header top section (title + counter) — parte izquierda
  const headerTop = document.createElement('div');
  headerTop.className = 'header-top';
  
  const headerLeft = document.createElement('div');
  headerLeft.className = 'header-left';
  
  const headerTitle = document.createElement('h4');
  headerTitle.className = 'header-title';
  headerTitle.innerHTML = '<span class="header-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 14l2 2 4-4"/></svg></span> Tareas Pendientes';
  
  const activityCounter = document.createElement('div');
  activityCounter.className = 'activity-counter activities';
  activityCounter.textContent = '0';
  
  headerLeft.appendChild(headerTitle);
  headerLeft.appendChild(activityCounter);
  headerTop.appendChild(headerLeft);
  
  // Create tab selector (custom dropdown) — parte derecha
  const tabSelector = document.createElement('div');
  tabSelector.className = 'tab-selector';
  
  const dropdownContainer = document.createElement('div');
  dropdownContainer.className = 'dropdown-container';
  
  // Create dropdown button — premium sin icono
  const dropdownButton = document.createElement('div');
  dropdownButton.className = 'dropdown-button';
  
  const buttonText = document.createElement('span');
  buttonText.textContent = 'Tareas';
  
  const dropdownArrow = document.createElement('span');
  dropdownArrow.className = 'dropdown-arrow';
  dropdownArrow.textContent = '▲';
  
  dropdownButton.appendChild(buttonText);
  dropdownButton.appendChild(dropdownArrow);
  
  // Create dropdown menu
  const dropdownMenu = document.createElement('div');
  dropdownMenu.className = 'dropdown-menu';
  
  // Premium sin emojis — iconos lineales sutiles
  const options = [
    { value: 'activities', icon: '', text: 'Tareas' },
    { value: 'exams', icon: '', text: 'Exámenes' },
    { value: 'forums', icon: '', text: 'Foros' }
  ];
  
  options.forEach(option => {
    const dropdownOption = document.createElement('div');
    dropdownOption.className = 'dropdown-option';
    dropdownOption.dataset.value = option.value;
    
    if (currentContentType === option.value) {
      dropdownOption.classList.add('selected');
      buttonText.textContent = option.text;
    }
    
    const optionText = document.createElement('span');
    optionText.className = 'dropdown-option-text';
    optionText.textContent = option.text;
    
    const optionCheck = document.createElement('span');
    optionCheck.className = 'dropdown-option-check';
    optionCheck.innerHTML = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12l5 5l10-10"/></svg>';
    optionCheck.setAttribute('aria-hidden', 'true');
    
    const optionInner = document.createElement('div');
    optionInner.className = 'dropdown-option-inner';
    optionInner.appendChild(optionText);
    optionInner.appendChild(optionCheck);
    
    dropdownOption.appendChild(optionInner);
    
    dropdownOption.addEventListener('click', () => {
      document.querySelectorAll('.dropdown-option').forEach(opt => opt.classList.remove('selected'));
      dropdownOption.classList.add('selected');
      buttonText.textContent = option.text;
      try{ if(typeof __ep_dd_close==='function') __ep_dd_close(); else { dropdownMenu.classList.remove('show'); dropdownButton.classList.remove('active'); } }catch{ dropdownMenu.classList.remove('show'); dropdownButton.classList.remove('active'); }
      switchContent(option.value);
    });
    
    dropdownMenu.appendChild(dropdownOption);
  });
  
  // FIX SISTÉMICO B: Dropdown portal fixed para escapar overflow:hidden/transform (detrás)
  let __ep_dd_parent = dropdownContainer;
  function __ep_dd_pos(){
    try{
      const r = dropdownButton.getBoundingClientRect();
      const w = 200;
      let left = r.right - w;
      if(left < 8) left = 8;
      if(left + w > window.innerWidth - 8) left = window.innerWidth - w - 8;
      let top = r.bottom + 8;
      if(top + 180 > window.innerHeight) top = Math.max(8, r.top - 180 - 8);
      dropdownMenu.style.left = left + 'px';
      dropdownMenu.style.top = top + 'px';
      dropdownMenu.style.right = 'auto';
    }catch{}
  }
  function __ep_dd_open(){
    if(dropdownMenu.parentElement !== document.body){
      __ep_dd_parent = dropdownContainer;
      document.body.appendChild(dropdownMenu);
      try { document.body.classList.add('ep-dd-detached'); } catch {}
    }
    __ep_dd_pos();
    dropdownMenu.classList.add('show');
    dropdownButton.classList.add('active');
    window.addEventListener('scroll', __ep_dd_pos, true);
    window.addEventListener('resize', __ep_dd_pos);
  }
  function __ep_dd_close(){
    dropdownMenu.classList.remove('show');
    dropdownButton.classList.remove('active');
    window.removeEventListener('scroll', __ep_dd_pos, true);
    window.removeEventListener('resize', __ep_dd_pos);
    setTimeout(()=>{ if(dropdownMenu.parentElement===document.body && __ep_dd_parent){ try{ __ep_dd_parent.appendChild(dropdownMenu); dropdownMenu.style.left=''; dropdownMenu.style.top=''; }catch{} } try{ if(!document.querySelector('body > .dropdown-menu.show')) document.body.classList.remove('ep-dd-detached'); }catch{} }, 320);
  }
  dropdownButton.addEventListener('click', (e) => {
    e.stopPropagation();
    const isOpen = dropdownMenu.classList.contains('show');
    const subjectDropdown = document.querySelector('.subject-filter-dropdown');
    if (subjectDropdown) subjectDropdown.classList.remove('open');
    if (isOpen) {
      __ep_dd_close();
    } else {
      __ep_dd_open();
    }
  });
  
  document.addEventListener('click', (e) => {
    if(e.target.closest('.dropdown-container') || e.target.closest('.dropdown-menu')) return;
    __ep_dd_close();
  });
  document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') __ep_dd_close(); });
  
  dropdownContainer.appendChild(dropdownButton);
  dropdownContainer.appendChild(dropdownMenu);
  tabSelector.appendChild(dropdownContainer);
  // parchea clicks de opciones para usar portal close
  setTimeout(()=>{
    dropdownMenu.querySelectorAll('.dropdown-option').forEach(opt=>{
      opt.addEventListener('click', ()=> setTimeout(__ep_dd_close, 80));
    });
  }, 0);
  
  // Assemble header — fijo, no colapsable
  headerContainer.appendChild(headerTop);
  headerContainer.appendChild(tabSelector);
  
  // Create content body — siempre visible
  const contentBody = document.createElement('div');
  contentBody.className = 'content-body';
  container.classList.add('expanded');
  
  // Create subject filter
  const filterContainer = document.createElement('div');
  filterContainer.className = 'filter-container';
  filterContainer.innerHTML = `
    <div class="subject-filter-dropdown">
      <div class="subject-filter-button" id="subject-filter-button">
        <span class="subject-filter-text">Todas las materias</span>
        <span class="subject-filter-arrow">▼</span>
      </div>
      <div class="subject-filter-menu" id="subject-filter-menu">
        <div class="subject-filter-option" data-value="all">Todas las materias</div>
      </div>
    </div>
    <label class="expired-toggle">
      <input type="checkbox" id="show-expired-toggle">
      <span>Mostrar vencidas</span>
    </label>
  `;
  
  // Create activities list — solo skeleton centrado, sin loader duplicado
  const activitiesList = document.createElement('div');
  activitiesList.className = 'acts-list';
  activitiesList.innerHTML = '<div class="skeleton-cards" style="margin: 0 auto; max-width: 320px;"><div class="skeleton-card"><div class="skeleton-line short"></div><div class="skeleton-line long"></div></div><div class="skeleton-card"><div class="skeleton-line short"></div><div class="skeleton-line long"></div></div></div>';
  
  contentBody.appendChild(filterContainer);
  contentBody.appendChild(activitiesList);
  
  // Append elements to container
  container.appendChild(headerContainer);
  container.appendChild(contentBody);
}

/**
 * Switches between different content types
 */
function switchContent(contentType) {
  console.log(`ðŸ”„ Switching to content type: ${contentType}`);
  currentContentType = contentType;
  
  // Update dropdown selection — sin icono
  const buttonText = document.querySelector('.dropdown-button span:nth-child(1)');
  const options = document.querySelectorAll('.dropdown-option');
  
  if (buttonText && options.length > 0) {
    options.forEach(option => option.classList.remove('selected'));
    const selectedOption = document.querySelector(`[data-value="${contentType}"]`);
    if (selectedOption) {
      selectedOption.classList.add('selected');
      const text = selectedOption.querySelector('.dropdown-option-text').textContent;
      buttonText.textContent = text;
    }
  }
  
  // Clear current content and show loader
  const activitiesList = document.querySelector('.acts-list');
  const headerTitle = document.querySelector('.header-title');
  const activityCounter = document.querySelector('.activity-counter');
  
  if (activitiesList) {
    activitiesList.innerHTML = '<div class="skeleton-cards" style="margin: 0 auto; max-width: 320px;"><div class="skeleton-card"><div class="skeleton-line short"></div><div class="skeleton-line long"></div></div></div>';
  }
  
  // Update header and counter immediately — FIX C: Solo tareas/exams/foros en widget principal
  if (headerTitle && activityCounter) {
    // Remove existing counter classes
    activityCounter.className = 'activity-counter';
    
    switch (contentType) {
      case 'activities':
        updateHeaderTitle(headerTitle, 'Tareas Pendientes');
        activityCounter.classList.add('activities');
        activityCounter.textContent = '0';
        break;
      case 'exams':
        updateHeaderTitle(headerTitle, 'Exámenes Disponibles');
        activityCounter.classList.add('exams');
        activityCounter.textContent = '0';
        break;
      case 'forums':
        updateHeaderTitle(headerTitle, 'Foros Activos');
        activityCounter.classList.add('forums');
        activityCounter.textContent = '0';
        break;
    }
  }
  
  // Get bearer token from localStorage and load specific content
  const bearerToken = localStorage.getItem("accessToken");
  
  if (!bearerToken) {
    console.error('❌ Access token not found in localStorage');
    if (activitiesList) {
      activitiesList.innerHTML = '<div class="error-message">Token de acceso no encontrado</div>';
    }
    return;
  }
  
  console.log(`✅ Token found, loading ${contentType} content...`);
  
  // Load content based on type — FIX C: Widgets independientes, horario/mensajes no comparten .acts-list
  switch (contentType) {
    case 'activities':
      loadActivitiesContent(bearerToken);
      break;
    case 'exams':
      loadExamsContent(bearerToken);
      break;
    case 'forums':
      loadForumsContent(bearerToken);
      break;
    default:
      console.error(`❌ Unknown content type: ${contentType}`);
  }
}

/**
 * Updates header title text
 */
function updateHeaderTitle(headerTitle, newText) {
  headerTitle.innerHTML = '<span class="header-icon"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2"/><rect x="9" y="3" width="6" height="4" rx="1"/><path d="M9 14l2 2 4-4"/></svg></span> ' + newText;
}

// Dueño del cache: sub/usuario del JWT (null si opaco). Evita pintar datos de otro usuario.
function __ep_tokenUser(tok){
  try{
    const t = String(tok || '');
    const parts = t.split('.');
    if(parts.length < 3) return null;
    let b64 = parts[1].replace(/-/g,'+').replace(/_/g,'/');
    while(b64.length % 4) b64 += '=';
    const j = JSON.parse(atob(b64));
    const u = j && (j.sub || j.username || j.preferred_username || j.unique_name || j.upn || j.email);
    return u ? String(u) : null;
  }catch{ return null; }
}

/**
 * Loads activities content independently
 */
async function loadActivitiesContent(bearerToken) {
  if (window.__ep_loadingActivities) return;
  window.__ep_loadingActivities = true;
  try {
    const activitiesList0 = document.querySelector('.acts-list');
    if (!activitiesList0) { console.error('❌ Activities list container not found'); return; }
    // FIX velocidad: caché instantánea + revalidación en fondo (SWR, 10 min fresca)
    let __ep_cachedActs = null;
    try {
      const __ep_c = await chrome.storage.local.get(['ep_acts_cache_v1']);
      if (__ep_c && __ep_c.ep_acts_cache_v1 && Array.isArray(__ep_c.ep_acts_cache_v1.items)) __ep_cachedActs = __ep_c.ep_acts_cache_v1;
    } catch {}
    // FIX multi-usuario: ignora cache de otro usuario (skeleton + fetch fresco, no datos ajenos)
    try{
      if(__ep_cachedActs && __ep_cachedActs.user){
        const _me = __ep_tokenUser(localStorage.getItem('accessToken'));
        if(_me && __ep_cachedActs.user !== _me){
          try{ __ep_log('cache de otro usuario, se ignora'); }catch{}
          __ep_cachedActs = null;
        }
      }
    }catch{}
    const __ep_actsFresh = !!(__ep_cachedActs && __ep_cachedActs.items.length && (Date.now() - (__ep_cachedActs.ts || 0)) < 10 * 60 * 1000);
    if (__ep_cachedActs && __ep_cachedActs.items.length) {
      try{ __ep_log('cache HIT n=' + __ep_cachedActs.items.length); }catch{}
      console.log('[EP] tareas: ' + __ep_cachedActs.items.length + ' desde caché' + (__ep_actsFresh ? ', refresh en fondo' : ''));
      try { await renderActivitiesList(__ep_cachedActs.items); } catch (e) { console.warn('[EP] render caché tareas falló', e); }
      if (__ep_actsFresh) {
        if (!window.__ep_acts_refreshing) {
          window.__ep_acts_refreshing = true;
          const __ep_oldCache = __ep_cachedActs;
          (async()=>{
            try{
              const fresh = await getAllPendingActivities(bearerToken);
              const freshArr = Array.isArray(fresh) ? fresh : [];
              // nunca sobrescribir cache bueno con vacio
              if(!freshArr.length && __ep_oldCache.items.length){
                try{ __ep_log('refresh vacio con cache bueno: conserva + retry'); }catch{}
                setTimeout(()=>{ try{
                  window.__ep_acts_refreshing = false;
                  const _t3 = localStorage.getItem('accessToken');
                  if(_t3 && !window.__ep_loadingActivities) loadActivitiesContent(_t3);
                }catch{} }, 6000);
                return;
              }
              try { await chrome.storage.local.set({ ep_acts_cache_v1: { items: freshArr, ts: Date.now(), user: __ep_tokenUser(bearerToken) } }); } catch {}
              const oldIds = __ep_oldCache.items.map(a => String(a && a.idActividad)).join(',');
              const newIds = freshArr.map(a => String(a && a.idActividad)).join(',');
              if (oldIds !== newIds && document.querySelector('.acts-list')) { try { await renderActivitiesList(freshArr); } catch {} }
            } catch {} finally { window.__ep_acts_refreshing = false; }
          })().catch(() => { window.__ep_acts_refreshing = false; });
        }
        return;
      }
    }
    console.log('🎯 Loading activities content (red)…');
    // FIX: fetch optimista inmediato (sin espera serial de validacion); si 401/vacio con
    // token cambiado a mitad, se reintenta abajo. Mas rapido siempre que validar antes.
    const activities = await getAllPendingActivities(bearerToken);
    try{ __ep_log('fetch done n=' + (Array.isArray(activities) ? activities.length : -1)); }catch{}
    const actsArr = Array.isArray(activities) ? activities : [];
    // FIX: si el token cambio durante el fetch (refresco silencioso ganado) -> reintenta con el nuevo
    try{
      const _tokNow = localStorage.getItem('accessToken');
      if(!actsArr.length && _tokNow && _tokNow !== bearerToken){
        window.__ep_emptyRetries = 0;
        try{ __ep_log('token cambio mid-fetch, retry'); }catch{}
        setTimeout(()=>{ try{ window.__ep_loadingActivities = false; loadActivitiesContent(_tokNow); }catch{} }, 1500);
        return;
      }
    }catch{}
    // FIX login: fetch vacio con cache previo (token recien refrescado) -> conserva y reintenta
    // (max 2), sin pintar vacio ni envenenar el cache. Vacio solo se guarda si nunca hubo datos.
    if(!actsArr.length && __ep_cachedActs && __ep_cachedActs.items.length){
      window.__ep_emptyRetries = window.__ep_emptyRetries || 0;
      if(window.__ep_emptyRetries < 2){
        window.__ep_emptyRetries++;
        try{ __ep_log('fetch empty con cache, retry ' + window.__ep_emptyRetries); }catch{}
        setTimeout(()=>{ try{
          const _t = localStorage.getItem('accessToken');
          window.__ep_loadingActivities = false;
          if(_t) loadActivitiesContent(_t);
        }catch{} }, 5000);
        return;
      }
      window.__ep_emptyRetries = 0;
    }
    if(actsArr.length){ window.__ep_emptyRetries = 0; window.__ep_emptyOnce = 0; }
    // FIX: vacio sin cache previo -> UN reintento antes de sentenciar (el token pudo refrescarse)
    if(!actsArr.length && !(__ep_cachedActs && __ep_cachedActs.items.length)){
      window.__ep_emptyOnce = window.__ep_emptyOnce || 0;
      if(window.__ep_emptyOnce < 1){
        window.__ep_emptyOnce++;
        try{ __ep_log('empty sin cache, 1 retry'); }catch{}
        setTimeout(()=>{ try{ window.__ep_loadingActivities = false; const _t0 = localStorage.getItem('accessToken'); if(_t0) loadActivitiesContent(_t0); }catch{} }, 4000);
        return;
      }
      window.__ep_emptyOnce = 0;
    }
    try { if(actsArr.length || !(__ep_cachedActs && __ep_cachedActs.items.length)) await chrome.storage.local.set({ ep_acts_cache_v1: { items: actsArr, ts: Date.now(), user: __ep_tokenUser(bearerToken) } }); } catch {}
    let __ep_same = false;
    try { __ep_same = !!(__ep_cachedActs && __ep_cachedActs.items.length && JSON.stringify(__ep_cachedActs.items) === JSON.stringify(actsArr)); } catch {}
    if (!__ep_same) await renderActivitiesList(actsArr);
  } catch (error) {
    console.error('❌ Error loading activities content:', error);
    try {
      const al = document.querySelector('.acts-list');
      if (al && !al.children.length) al.innerHTML = '<div class="error-message">Error al cargar las tareas</div>';
    } catch {}
  } finally { window.__ep_loadingActivities = false; window.__ep_tasksPainted = true; }
}

// IA bajo demanda: genera el resumen con el worker SOLO al expandir el asistente
// de la tarea. Al renderizar y en backfill JAMÁS se toca el worker (cuota).
// El resultado se cachea (ep_ai3_<id>) y no se vuelve a pedir.
async function __ep_lazySummary(activity, cardEl){
  try{
    const miniEl = cardEl.querySelector('[data-ai-mini]');
    if(!miniEl) return;
    if(miniEl.dataset.epDone==='1') return;
    const raw = activity.descripcionOriginal || '';
    if(!raw || !String(raw).trim()){
      const fb = (activity.descripcion && activity.descripcion!=='Sin descripción') ? activity.descripcion : 'Sin descripción';
      miniEl.textContent = fb; miniEl.dataset.epDone='1';
      try{ const sub=cardEl.querySelector('.ai-subtitle-spec'); if(sub) sub.textContent='Toca para expandir'; }catch{}
      return;
    }
    miniEl.textContent = 'Generando resumen con IA…';
    let s = '';
    try{ s = await getDescription(activity.idActividad, raw); }catch{ s=''; }
    if(!s || /^IA no disponible/i.test(String(s)) || s==='Sin descripción'){
      miniEl.textContent = s || 'IA no disponible — expande de nuevo para reintentar';
      return; // sin marcar done: reintenta en la próxima expansión
    }
    miniEl.textContent = s; miniEl.dataset.epDone='1';
    try{ activity.descripcion = s; }catch{}
    try{ const sub=cardEl.querySelector('.ai-subtitle-spec'); if(sub) sub.textContent='Toca para expandir • Resumen listo'; }catch{}
  }catch{}
}
// FIX: render separado para reutilizar con caché instantánea (SWR)
// Rellena descripciones faltantes en FONDO (tras pintar): solo detalle de Eminus,
// NUNCA worker (la IA es bajo demanda al expandir). Un solo vuelo.
async function __ep_descBackfill(items){
  try{
    if(window.__ep_descBackfillOn) return;
    window.__ep_descBackfillOn = true;
    const list = (Array.isArray(items)?items:[]).filter(a=>a && (!a.descripcionOriginal || !String(a.descripcionOriginal).trim()));
    if(!list.length){ window.__ep_descBackfillOn = false; return; }
    const tok = localStorage.getItem('accessToken');
    if(!tok){ window.__ep_descBackfillOn = false; return; }
    const CH = 5;
    let _touched = false;
    for(let c=0;c<list.length;c+=CH){
      const chunk = list.slice(c, c+CH);
      await Promise.all(chunk.map(async (a)=>{
        try{
          let raw = '';
          try{ raw = await Promise.race([fetchActivityDetail(tok, a.idCurso, a.idActividad), new Promise(res=>setTimeout(()=>res(''), 4000))]) || ''; }catch{ raw=''; }
          if(!raw || !String(raw).trim()) return;
          a.descripcionOriginal = String(raw);
          _touched = true;
          // IA bajo demanda: el backfill NO llama al worker (cuota). Guarda extracto
          // local; el resumen con IA se genera al expandir el asistente.
          let s = '';
          try{ s = __ep_excerpt(raw); }catch{ s=''; }
          if(s) a.descripcion = s;
          try{
            const inp = document.getElementById('ai-card-' + a.idActividad + '-input');
            const scope = (inp && inp.closest) ? inp.closest('.act-item') : null;
            const mini = scope ? scope.querySelector('[data-ai-mini]') : null;
            if(mini) mini.textContent = s || __ep_excerpt(raw);
          }catch{}
        }catch{}
      }));
    }
    try{
      if(_touched){
        const cur = await chrome.storage.local.get(['ep_acts_cache_v1']);
        if(cur && cur.ep_acts_cache_v1 && Array.isArray(cur.ep_acts_cache_v1.items) && cur.ep_acts_cache_v1.items.length){
          const byId = {};
          list.forEach(a=>{ if(a.descripcionOriginal) byId[String(a.idActividad)] = a; });
          let changed = false;
          cur.ep_acts_cache_v1.items.forEach(it=>{
            const b = byId[String(it.idActividad)];
            if(b && (!it.descripcionOriginal || !String(it.descripcionOriginal).trim())){ it.descripcionOriginal = b.descripcionOriginal; if(b.descripcion) it.descripcion = b.descripcion; changed = true; }
          });
          if(changed) await chrome.storage.local.set({ep_acts_cache_v1: cur.ep_acts_cache_v1});
        }
      }
    }catch{}
  }catch{}
  try{ window.__ep_descBackfillOn = false; }catch{}
}
async function renderActivitiesList(activities) {
  const activitiesList = document.querySelector('.acts-list');
  if (!activitiesList) return;
  try {
    
    // Clear loading state
    activitiesList.innerHTML = '';
    
    if (activities.length === 0) {
      activitiesList.innerHTML = getEmptyStateHTML('tasks');
      const ac0 = document.querySelector('.activity-counter');
      if (ac0) ac0.textContent = '0';
      updateEmptyState();
      return;
    }

    // Sort activities by urgency (least days remaining first)
    activities.sort((a, b) => {
      const deadlineA = new Date(a.fechaTermino);
      const deadlineB = new Date(b.fechaTermino);
      return deadlineA - deadlineB; // Earlier dates first
    });
    
    // Update counter in header
    const activityCounter = document.querySelector('.activity-counter');
    if (activityCounter) {
      activityCounter.textContent = activities.length;
    }
    
    // FIX SISTÉMICO: Render chunked con yield para no freezar después de cargar cursos (30 actividades * innerHTML + AI bloqueaba 800ms)
    for(let _rIdx=0; _rIdx<activities.length; _rIdx++){
      const activity = activities[_rIdx];
      if(_rIdx%5===0 && _rIdx!==0) await new Promise(r=> (window.requestIdleCallback||function(cb){return setTimeout(cb,16)})(r));
      console.log(`ðŸŽ¯ Rendering activity: "${_rIdx+1}/${activities.length} "${activity.titulo}" with courseName="${activity.courseName}"`);
      
      const activityItem = document.createElement('div');
      const daysLeftInfo = getDaysLeftInfo(activity.fechaTermino);
      activityItem.className = `act-item activity ${daysLeftInfo.urgencyClass}`;
      if (daysLeftInfo.class === 'expired') {
        activityItem.dataset.expired = 'true';
        activityItem.style.display = 'none';
      }
      
      const deadline = new Date(activity.fechaTermino);
      const dateStr = deadline.toLocaleDateString("es-MX");
      const timeStr = deadline.toLocaleTimeString("es-MX", { hour: '2-digit', minute: '2-digit' });
      
      // SPEC v1.0: Estructura exacta con IA integrada
      const taskContext = `La actividad es: '${activity.titulo}' del curso ${activity.courseName || activity.course}. La descripción dice: ${activity.descripcionOriginal || activity.descripcion || 'Sin descripción'}. Vale ${activity.valor || 0} puntos y la entrega es el ${dateStr} a las ${timeStr}. ${daysLeftInfo.text}.`;
      const cardId = `ai-card-${activity.idActividad}`;
      activityItem.innerHTML = `
        <div class="card-body-spec">
          <div class="course-name-spec">${sanitizeHTML((activity.courseName || 'Curso').toUpperCase())}</div>
          <div class="title-row-spec">
            <h3 class="title-spec">${sanitizeHTML(activity.titulo)}</h3>
            <span class="score-pill-spec">${activity.valor || 0} pts</span>
          </div>
          <div class="info-row-spec">
            <span class="chip-spec"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg> ${dateStr}</span>
            <span class="chip-spec"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> ${timeStr}</span>
          </div>
          <div class="ai-section-spec is-collapsed" data-context="${sanitizeHTML(taskContext).replace(/"/g,'&quot;')}">
            <div class="ai-header-spec" data-toggle="">
              <div style="display:flex;align-items:center;gap:7px;">
                <div class="ai-icon-box-spec"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l1.7 4.3L18 9l-4.3 1.7L12 15l-1.7-4.3L6 9l4.3-1.7z"/><path d="M19 13l1 2.5L22.5 17 20 18.5 19 21l-1-2.5L15.5 17 18 15.5z"/><path d="M5 15l1 2.5L8.5 19 6 20.5 5 23l-1-2.5L1.5 19 4 17.5z"/></svg></div>
                <div>
                  <p class="ai-title-spec">Asistente de tarea</p>
                  <p class="ai-subtitle-spec">Toca para expandir</p>
                </div>
              </div>
              <span class="ai-chevron-spec">▼</span>
            </div>
            <div class="ai-collapsible-spec">
              <div class="ai-mini-desc-spec" data-ai-mini="1">El resumen con IA se genera al expandir el asistente</div>
              <!-- Chips eliminados por petición — se mantiene input directo -->
              <div class="ask-row-spec">
                <input class="ask-input-spec" id="${cardId}-input" placeholder="Pregunta sobre esta tarea…" />
                <button class="ask-btn-spec" id="${cardId}-ask" aria-label="Enviar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13"/><path d="M22 2L15 22L11 13L2 9L22 2z"/></svg></button>
              </div>
              <div class="ask-error-spec" id="${cardId}-error">Escribe una pregunta primero.</div>
            </div>
          </div>
          <div class="footer-row-spec">
            <span class="urgency-pill-spec"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span class="pill-label">${daysLeftInfo.text}</span></span>
            <button class="btn-solid-spec view-activity-btn"><span class="btn-label">Ver actividad</span><span class="btn-chevron"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M9 18l6-6-6-6"/></svg></span></button>
          </div>
        </div>
      `;
      
      // Add click event to the view button — premium con spring Apple
      const viewBtn = activityItem.querySelector('.view-activity-btn');
      viewBtn.addEventListener('click', () => navigateToActivity(activity.idCurso, activity.idActividad));
      // AI colapsable — Apple spring, mini descripción visible al expandir
      const aiSection = activityItem.querySelector('.ai-section-spec');
      const aiHeader = activityItem.querySelector('.ai-header-spec');
      if (aiHeader) {
        aiHeader.addEventListener('click', () => {
          const isCollapsed = aiSection.classList.contains('is-collapsed');
          // Apple: anima desde valor actual, sin salto
          aiSection.classList.toggle('is-collapsed', !isCollapsed);
          aiSection.classList.toggle('is-expanded', isCollapsed);
          // IA bajo demanda: el resumen (worker) solo se genera al expandir
          if(isCollapsed){ try{ __ep_lazySummary(activity, activityItem); }catch{} }
        });
      }
      // Mini-resumen: SOLO caché local al renderizar (gratis, sin worker).
      // El worker se consulta únicamente al expandir (__ep_lazySummary).
      try {
        const miniEl = activityItem.querySelector('[data-ai-mini]');
          // Solo descripcionOriginal (texto real) admite resumen; el extracto se muestra tal cual.
          // Sin worker al renderizar: si hay caché se muestra, si no un aviso neutro.
          const rawMini = activity.descripcionOriginal || "";
          if (!rawMini || !String(rawMini).trim()) { if (miniEl) miniEl.textContent = (activity.descripcion && activity.descripcion !== "Sin descripción") ? activity.descripcion : "Sin descripción"; }
        else if (miniEl) {
          __ep_descFast(activity.idActividad).then(cached => {
            try{
              const sub = activityItem.querySelector('.ai-subtitle-spec');
              if(cached){ miniEl.textContent = cached; miniEl.dataset.epDone='1'; if(sub) sub.textContent='Toca para expandir • Resumen listo'; }
              else { miniEl.textContent = 'El resumen con IA se genera al expandir el asistente'; if(sub) sub.textContent='Toca para expandir • IA bajo demanda'; }
            }catch{}
          }).catch(()=>{});
        }
      } catch {}
      // AI logic per card — chips, input, ask, typing 14ms
      let aiResponse = activityItem.querySelector(`#${cardId}-response`);
      const aiInput = activityItem.querySelector(`#${cardId}-input`);
      const aiAsk = activityItem.querySelector(`#${cardId}-ask`);
      const aiError = activityItem.querySelector(`#${cardId}-error`);
      const aiChips = activityItem.querySelectorAll('.chip-btn-spec');
      async function callAI(question) {
        const ctx = normalizeAIText(activityItem.querySelector('.ai-section-spec')?.dataset.context || taskContext);
        // Solo LLM remoto: sin fast-paths locales, todo va al Worker
        aiError.style.display = 'none';
        aiSection.classList.remove('is-collapsed');
        aiSection.classList.add('is-expanded');
        if (!aiResponse) {
          aiResponse = document.createElement('div');
          aiResponse.className = 'ai-response-spec has-content';
          aiResponse.id = `${cardId}-response`;
          const askRow = activityItem.querySelector('.ask-row-spec');
          askRow.insertAdjacentElement('beforebegin', aiResponse);
        }
        // Percepción premium: thinking aparece instantáneo (pointerdown) y se siente rápido
        const thinkingHTML = `<div class="thinking-spec"><div class="dots-spec"><span class="dot-spec"></span><span class="dot-spec"></span><span class="dot-spec"></span></div><span>Pensando…</span></div>`;
        aiResponse.innerHTML = thinkingHTML;
        aiResponse.style.display = 'block';
        const thinkingStart = Date.now();
        try {
          const meta = { titulo: activity.titulo || '', curso: activity.courseName || activity.course || '', vence: (daysLeftInfo && daysLeftInfo.text) || '', valor: activity.valor || 0, fecha: dateStr + ' ' + timeStr };
          const respPromise = chrome.runtime.sendMessage({ action: 'aiAsk', question: normalizeAIText(question), context: ctx, meta });
          // Asegura mínimo 350ms de thinking para evitar flicker, pero no más de 900ms de espera percibida
          const [resp] = await Promise.all([respPromise, new Promise(r => setTimeout(r, 380))]);
          if (resp && resp.error) throw new Error(resp.error);
          let raw = resp?.answer || resp?.summary || '';
          if (!raw || !String(raw).trim()) throw new Error(resp?.error || 'IA no disponible — reintenta en unos segundos');
          if (String(raw).trim().startsWith('{') && String(raw).includes('"summary"')) {
            try { const j = JSON.parse(raw); raw = j.summary || j.answer || raw; } catch {}
          }
          if (/The user wants a one-sentence summary|Based on the provided context|Key elements to include|Here.?s a thinking process|system-reminder|Your operational mode has changed/i.test(raw)) {
            throw new Error("thinking-leak");
          }
          let html = normalizeAIText(raw);
          // Si la respuesta llegó muy rápido (<400ms), mantiene thinking 80ms extra para ritmo natural
          const elapsed = Date.now() - thinkingStart;
          if (elapsed < 400) await new Promise(r => setTimeout(r, 90));
          aiResponse.innerHTML = '';
          aiResponse.classList.add('has-content');
          aiResponse.style.whiteSpace = 'normal';
          // Typing seguro: no corta dentro de tags <...>
          let i = 0;
          const step = html.length > 400 ? 6 : 4;
          const iv = setInterval(() => {
            let end = Math.min(i, html.length);
            // si corta dentro de tag, extiende hasta >
            const slice = html.slice(0, end);
            const lastOpen = slice.lastIndexOf('<');
            const lastClose = slice.lastIndexOf('>');
            if (lastOpen > lastClose) {
              const nextClose = html.indexOf('>', end);
              if (nextClose !== -1) end = nextClose + 1;
            }
            aiResponse.innerHTML = html.slice(0, end);
            // auto-scroll suave al final del mensaje
            try { aiResponse.scrollTop = aiResponse.scrollHeight; } catch {}
            i += step;
            if (i >= html.length) { aiResponse.innerHTML = html; clearInterval(iv); }
          }, 7);
        } catch (e) {
          // Solo LLM remoto: muestra el error real, sin resumidor local
          const msg = (e && e.message) ? String(e.message) : 'IA no disponible — reintenta en unos segundos';
          aiResponse.innerHTML = `<div style="font-size:12.5px;line-height:1.6;">${sanitizeHTML(msg)}</div>`;
          aiResponse.classList.add('has-content');
        }
      }
      aiChips.forEach(chip => chip.addEventListener('click', () => { aiInput.value = chip.dataset.q; callAI(chip.dataset.q); }));
      aiAsk.addEventListener('click', () => {
        const q = aiInput.value.trim();
        if (!q) { aiError.style.display = 'block'; return; }
        aiError.style.display = 'none';
        callAI(q);
        aiInput.value = '';
      });
      aiInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); aiAsk.click(); } });
      aiInput.addEventListener('input', () => { aiError.style.display = 'none'; });
      
      activitiesList.appendChild(activityItem);
    }
    // Asegura vacío visible si todo quedó oculto (fix 0 sin nada)
    updateEmptyState();
    try{ __ep_perfMark('data'); }catch{}
    // Backfill diferido: descripciones faltantes (detalle + IA) sin bloquear; parchea tarjetas
    try{ __ep_descBackfill(activities); }catch{}
    // Populate subject filter after activities are rendered
    setTimeout(() => {
      populateSubjectFilter();
      setupExpiredToggle();
    }, 100);
    // FIX: al terminar tareas, reintenta facilitadores (ya hay datos cosechados por curso)
    try { if (typeof injectFacilitators === 'function') injectFacilitators(); } catch {}
    
  } catch (e) {
    console.error('❌ Error renderizando tareas:', e);
    try {
      if (activitiesList && !activitiesList.children.length) activitiesList.innerHTML = '<div class="error-message">Error al cargar las tareas</div>';
    } catch {}
  }
}

/**
 * Loads exams content independently
 */
async function loadExamsContent(bearerToken) {
  try {
    console.log('ðŸŽ¯ Loading exams content...');
    const activitiesList = document.querySelector('.acts-list');
    
    if (!activitiesList) {
      console.error('❌ Activities list container not found');
      return;
    }
    
    // Get courses first - only active ones
    const courses = await getAllCourses(bearerToken);
    console.log(`ðŸ“š Found ${courses.length} active courses for exams`);
    
    const allExams = [];
    const now = new Date();
    
    // Fetch exams for each active course
    for (const courseWrapper of courses) {
      const courseId = courseWrapper.curso.idCurso;
      const courseName = courseWrapper.curso.nombre;
      const courseEndDate = new Date(courseWrapper.curso.fechaTermino);
      
      // Skip courses that have ended more than 7 days ago
      if (courseEndDate < (now.getTime() - (7 * 24 * 60 * 60 * 1000))) {
        console.log(`⏭ï¸ Skipping expired course: ${courseName}`);
        continue;
      }
      
      console.log(`ðŸ” Fetching exams for active course: ${courseName} (ID: ${courseId})`);
      
      try {
        const exams = await makeApiRequest(
          bearerToken,
          `${API_ENDPOINTS.EXAMS}/${courseId}`,
          "https://eminus.uv.mx/eminus4/page/course/exam"
        );
        
        if (exams && exams.length > 0) {
          console.log(`ðŸ“ Found ${exams.length} exams for course ${courseName}`);
          
          // Filter exams that are still relevant
          const relevantExams = exams.filter(exam => {
            const examEndDate = new Date(exam.fechaTermino);
            const isNotExpired = examEndDate > (now.getTime() - (7 * 24 * 60 * 60 * 1000));
            const isNotCompleted = exam.estadoAvance !== 2; // Assuming 2 is completed
            
            console.log(`ðŸ“ Exam "${exam.nombre || exam.titulo}": end=${examEndDate.toLocaleDateString()}, expired=${!isNotExpired}, completed=${!isNotCompleted}`);
            
            return isNotExpired && isNotCompleted;
          });
          
          // Add course information to each relevant exam
          const examsWithCourse = relevantExams.map(exam => ({
            ...exam,
            courseId: courseId,
            courseName: courseName
          }));
          
          allExams.push(...examsWithCourse);
        }
      } catch (error) {
        console.error(`❌ Error fetching exams for course ${courseName}:`, error);
      }
    }
    
    // Clear loading state
    activitiesList.innerHTML = '';
    
    if (allExams.length === 0) {
      activitiesList.innerHTML = getEmptyStateHTML('exams');
      const ac0 = document.querySelector('.activity-counter');
      if (ac0) ac0.textContent = '0';
      updateEmptyState();
      return;
    }

    // Sort exams by urgency (least days remaining first)
    allExams.sort((a, b) => {
      const deadlineA = new Date(a.fechaTermino);
      const deadlineB = new Date(b.fechaTermino);
      return deadlineA - deadlineB; // Earlier dates first
    });
    
    // Update counter in header
    const activityCounter = document.querySelector('.activity-counter');
    if (activityCounter) {
      activityCounter.textContent = allExams.length;
    }
    
    // Render each exam
    allExams.forEach(exam => {
      const examItem = document.createElement('div');
      examItem.className = 'act-item exam';
      
      const startDate = exam.fechaInicio ? new Date(exam.fechaInicio) : null;
      const endDate = exam.fechaTermino ? new Date(exam.fechaTermino) : null;
      const endDateStr = endDate ? endDate.toLocaleDateString("es-MX") : 'No definida';
      const endTimeStr = endDate ? endDate.toLocaleTimeString("es-MX", { hour: '2-digit', minute: '2-digit' }) : '';
      const daysLeftInfo = endDate ? getDaysLeftInfo(exam.fechaTermino) : null;
      
      if (daysLeftInfo && daysLeftInfo.class === 'expired') {
        examItem.dataset.expired = 'true';
        examItem.style.display = 'none';
      }
      
      examItem.innerHTML = `
        <div class="d-flex flex-column">
          <div class="activity-header d-flex justify-content-between align-items-center">
            <h6 class="font-weight-bold mb-0 text-danger">
              ${exam.courseName}
            </h6>
          </div>
          <p class="activity-title">${exam.nombre || exam.titulo}</p>
          <div class="activity-date-time">
            <span class="activity-date">${endDateStr}</span>
            ${endTimeStr ? `<span class="activity-time">${endTimeStr}</span>` : ''}
          </div>
          <div class="activity-footer">
            <div class="d-flex justify-content-between align-items-center">
              <small class="text-muted">Inicio: ${startDate ? startDate.toLocaleDateString("es-MX") : 'No definida'}</small>
              <button class="btn btn-danger btn-sm view-exam-btn">
                Ver
              </button>
            </div>
            ${daysLeftInfo ? `<div class="d-flex justify-content-start"><span class="activity-days-left ${daysLeftInfo.class}">${daysLeftInfo.text}</span></div>` : ''}
          </div>
        </div>
      `;
      
      // Add click event to the view button
      const viewBtn = examItem.querySelector('.view-exam-btn');
      viewBtn.addEventListener('click', () => {
        console.log(`ðŸŽ¯ Navigating to exam: courseId=${exam.courseId}, examId=${exam.idExamen || exam.examenId}`);
        navigateToExam(exam.courseId, exam.idExamen || exam.examenId);
      });
      
      activitiesList.appendChild(examItem);
    });

    console.log(`✅ Loaded ${allExams.length} relevant exams from active courses`);
    
    // Re-initialize filters for exams
    setTimeout(() => {
      populateSubjectFilter();
      setupExpiredToggle();
    }, 100);
  } catch (error) {
    console.error('❌ Error loading exams content:', error);
    const activitiesList = document.querySelector('.acts-list');
    if (activitiesList) {
      activitiesList.innerHTML = '<div class="error-message">Error al cargar los exámenes</div>';
    }
  }
}

