// Descarga de adjuntos de mensajes: la URL válida es
// /eminusapi/api/centromensajes/descargaCentroMensajesArchivo/{idMensaje}/{idArchivosMensajes}
// (la `ruta` del detalle NO es descargable directa → daba 404). Se pide con Bearer,
// se respeta el filename del content-disposition y se dispara download por blob.
function __ep_bindMailDownload(){
  try{
    if(window.__ep_dlBound) return; window.__ep_dlBound = true;
    document.addEventListener('click', (e)=>{
      try{
        const t = e.target && e.target.closest ? e.target.closest('[data-ep-dl]') : null;
        if(!t || t.disabled) return;
        const parts = String(t.getAttribute('data-ep-dl')||'').split('/');
        if(parts.length!==2 || !parts[0] || !parts[1]) return;
        e.preventDefault(); e.stopPropagation();
        __ep_downloadMailFile(parts[0], parts[1], t);
      }catch{}
    }, true);
  }catch{}
}
async function __ep_downloadMailFile(idMsg, idFile, btn){
  const lab = btn.querySelector('[data-ep-dl-label]');
  const orig = lab ? lab.textContent : '';
  try{
    btn.disabled = true;
    if(lab) lab.textContent = 'Descargando…';
    const tok = localStorage.getItem('accessToken');
    const url = 'https://eminus.uv.mx/eminusapi/api/centromensajes/descargaCentroMensajesArchivo/' + encodeURIComponent(idMsg) + '/' + encodeURIComponent(idFile);
    const r = await fetch(url, { headers: tok ? { 'Authorization': 'Bearer ' + tok } : {} });
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const blob = await r.blob();
    let name = '';
    try{
      const cd = r.headers.get('content-disposition') || '';
      const m = cd.match(/filename\*=UTF-8''([^;]+)|filename="?([^";]+)"?/i);
      if(m) name = decodeURIComponent(m[1] || m[2]);
    }catch{}
    if(!name){ try{ name = decodeURIComponent(btn.getAttribute('data-ep-dlname') || ''); }catch{} }
    if(!name) name = 'archivo';
    const obj = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = obj; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>{ try{ URL.revokeObjectURL(obj); }catch{} }, 15000);
    if(lab) lab.textContent = orig;
  }catch(err){
    try{ console.warn('[EP] descarga adjunto', err); }catch{}
    if(lab) lab.textContent = 'Error al descargar, reintenta';
    setTimeout(()=>{ try{ if(lab) lab.textContent = orig; }catch{} }, 2500);
  }finally{
    try{ btn.disabled = false; }catch{}
  }
}
